// Thin C++ wrapper around the acados solver generated by scripts/export_c_code.py.
// Same initialisation and step logic as vnmpc.nmpc.NMPC (checked in test/test_solver.cpp).
#pragma once

#include <array>
#include <vector>

#include "vehicle_nmpc_ros/vehicle_model.hpp"

namespace vehicle_nmpc
{

struct SolveResult
{
  Input u{};             // input to apply now
  double next_delta = 0;  // predicted steering angle at the next node
  double next_vx = 0;     // predicted speed at the next node
  double solve_time_ms = 0;  // acados time_tot
  int status = 0;
};

class NmpcSolver
{
public:
  NmpcSolver();
  ~NmpcSolver();
  NmpcSolver(const NmpcSolver &) = delete;
  NmpcSolver & operator=(const NmpcSolver &) = delete;

  // Friction for the planning model and the constraints (no rebuild needed).
  void set_friction(double mu_model, double mu_limit);
  double mu_limit() const {return mu_limit_;}

  // One control step from the measured state (real-time iteration).
  SolveResult step(const State & x0);

  // Forget the warm start; the next step initialises from a straight-line guess.
  void reset() {initialized_ = false;}

  int horizon() const;
  std::vector<double> time_steps() const;

private:
  void init_guess(const State & x0);
  void set_x0(const State & x0);

  void * capsule_ = nullptr;  // vehicle_nmpc_solver_capsule*
  bool initialized_ = false;
  double mu_model_ = 1.0, mu_limit_ = 1.0;
};

}  // namespace vehicle_nmpc
